import BenchmarkTools
using Printf

# Benchmark variables:
name = "truncbf";
repeats = 3;

"""
	print_version()

Prints the TAP version.

# Examples

``` julia
julia> print_version()
```
"""
function print_version()
	@printf( "TAP version 13\n" );
end

"""
	print_summary( total, passing )

Prints the benchmark summary.

# Arguments

* `total`: total number of tests
* `passing`: number of passing tests

# Examples

``` julia
julia> print_summary( 3, 3 )
```
"""
function print_summary( total, passing )
	@printf( "#\n" );
	@printf( "1..%d\n", total ); # TAP plan
	@printf( "# total %d\n", total );
	@printf( "# pass  %d\n", passing );
	@printf( "#\n" );
	@printf( "# ok\n" );
end

"""
	print_results( elapsed )

Prints benchmark results.

# Arguments

* `elapsed`: elapsed time (in seconds)

# Examples

``` julia
julia> print_results( 0.5 )
```
"""
function print_results( elapsed )
	rate = 1.0 / elapsed;
	@printf( "  ---\n" );
	@printf( "  iterations: 1\n" );
	@printf( "  elapsed: %0.9f\n", elapsed );
	@printf( "  rate: %0.9f\n", rate );
	@printf( "  ...\n" );
end

"""
	truncbf( x, n, b )

Rounds a single-precision floating-point number toward zero to `n` digits in base `b`.

# Arguments

* `x`: input value
* `n`: number of digits
* `b`: base

# Returns

* `y`: rounded value

# Examples

``` julia
julia> y = truncbf( 3.14159f0, 2, 10 )
3.14f0
```
"""
function truncbf( x::Float32, n::Int32, b::Int32 )
	if x == 0.0f0 || isnan( x ) || isinf( x )
		return x;
	end
	if b == 0
		return NaN32;
	end
	s = Float64( b ) ^ Float64( n );
	y = trunc( Float64( x ) * s ) / s;
	return Float32( y );
end

"""
	benchmark()

Runs the benchmark.

# Examples

``` julia
julia> benchmark()
```
"""
function benchmark()
	t = @timed truncbf( 3.14159f0, 2, Int32( 10 ) );
	return t.time;
end

"""
	main()

Runs the benchmarks.

# Examples

``` julia
julia> main()
```
"""
function main()
	print_version();
	for i in 1:repeats
		@printf( "# julia::%s\n", name );
		elapsed = benchmark();
		print_results( elapsed );
		@printf( "ok %d benchmark finished\n", i );
	end
	print_summary( repeats, repeats );
end

main();
